class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not t or len(t)>len(s):return ""
        need=Counter(t);have={};formed=0;required=len(need);left=0;best=(float('inf'),0,0)
        for right,ch in enumerate(s):
            have[ch]=have.get(ch,0)+1
            if ch in need and have[ch]==need[ch]:formed+=1
            while formed==required:
                if right-left+1<best[0]:best=(right-left+1,left,right+1)
                drop=s[left];have[drop]-=1
                if drop in need and have[drop]<need[drop]:formed-=1
                left+=1
        return "" if best[0]==float('inf') else s[best[1]:best[2]]

