    public String minWindow(String s,String t) {
        if(t.isEmpty()||t.length()>s.length())return "";Map<Character,Integer>need=new HashMap<>(),have=new HashMap<>();for(char c:t.toCharArray())need.merge(c,1,Integer::sum);
        int formed=0,left=0,bestLen=Integer.MAX_VALUE,bestL=0,required=need.size();
        for(int right=0;right<s.length();right++){char c=s.charAt(right);have.merge(c,1,Integer::sum);if(need.containsKey(c)&&have.get(c).intValue()==need.get(c).intValue())formed++;
