    def subsets(self, nums: List[int]) -> List[List[int]]:
        out=[];path=[]
        def dfs(i):
            if i==len(nums):out.append(path.copy());return
            dfs(i+1);path.append(nums[i]);dfs(i+1);path.pop()
        dfs(0);return out

import java.util.*;

class Solution {
    public List<List<Integer>> subsets(int[] nums){List<List<Integer>>out=new ArrayList<>();dfs(nums,0,new ArrayList<>(),out);return out;}
    private void dfs(int[]a,int i,List<Integer>p,List<List<Integer>>out){if(i==a.length){out.add(new ArrayList<>(p));return;}dfs(a,i+1,p,out);p.add(a[i]);dfs(a,i+1,p,out);p.remove(p.size()-1);}
}

