class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        m,n=len(board),len(board[0])
        if len(word)>m*n:return False
        def dfs(r,c,i):
            if i==len(word):return True
            if r<0 or r>=m or c<0 or c>=n or board[r][c]!=word[i]:return False
            ch=board[r][c];board[r][c]='#'
            found=dfs(r+1,c,i+1) or dfs(r-1,c,i+1) or dfs(r,c+1,i+1) or dfs(r,c-1,i+1)
            board[r][c]=ch;return found
        for r in range(m):
            for c in range(n):
                if dfs(r,c,0):return True
        return False

class Solution {
    public boolean exist(char[][] board,String word){if(word.length()>board.length*board[0].length)return false;for(int r=0;r<board.length;r++)for(int c=0;c<board[0].length;c++)if(dfs(board,word,r,c,0))return true;return false;}
    private boolean dfs(char[][]b,String w,int r,int c,int i){if(i==w.length())return true;if(r<0||r>=b.length||c<0||c>=b[0].length||b[r][c]!=w.charAt(i))return false;char old=b[r][c];b[r][c]='#';boolean found=dfs(b,w,r+1,c,i+1)||dfs(b,w,r-1,c,i+1)||dfs(b,w,r,c+1,i+1)||dfs(b,w,r,c-1,i+1);b[r][c]=old;return found;}
}

