class Solution:
    def search(self, nums: List[int], target: int) -> bool:
        left,right=0,len(nums)-1
        while left<=right:
            mid=(left+right)//2
            if nums[mid]==target:return True
            if nums[left]==nums[mid]==nums[right]:left+=1;right-=1
            elif nums[left]<=nums[mid]:
                if nums[left]<=target<nums[mid]:right=mid-1
                else:left=mid+1
            else:
                if nums[mid]<target<=nums[right]:left=mid+1
                else:right=mid-1
        return False

class Solution {
    public boolean search(int[] nums,int target){int l=0,r=nums.length-1;while(l<=r){int m=l+(r-l)/2;if(nums[m]==target)return true;if(nums[l]==nums[m]&&nums[m]==nums[r]){l++;r--;}else if(nums[l]<=nums[m]){if(nums[l]<=target&&target<nums[m])r=m-1;else l=m+1;}else{if(nums[m]<target&&target<=nums[r])l=m+1;else r=m-1;}}return false;}
}

