class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummy=ListNode(0,head);prev=dummy
        while prev.next:
            if prev.next.next and prev.next.val==prev.next.next.val:
                value=prev.next.val
                while prev.next and prev.next.val==value:prev.next=prev.next.next
            else:prev=prev.next
        return dummy.next

class Solution {
    public ListNode deleteDuplicates(ListNode head){ListNode d=new ListNode(0,head),p=d;while(p.next!=null){if(p.next.next!=null&&p.next.val==p.next.next.val){int v=p.next.val;while(p.next!=null&&p.next.val==v)p.next=p.next.next;}else p=p.next;}return d.next;}
}

