class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix:return 0
        heights=[0]*len(matrix[0]);best=0
        for row in matrix:
            for c,ch in enumerate(row):heights[c]=heights[c]+1 if ch=='1' else 0
            stack=[];h=heights+[0]
            for i,v in enumerate(h):
                while stack and h[stack[-1]]>v:
                    height=h[stack.pop()];left=stack[-1] if stack else -1;best=max(best,height*(i-left-1))
                stack.append(i)
        return best

class Solution {
    public int maximalRectangle(char[][] matrix){if(matrix.length==0)return 0;int n=matrix[0].length,best=0;int[]h=new int[n];for(char[]row:matrix){for(int c=0;c<n;c++)h[c]=row[c]=='1'?h[c]+1:0;int[]st=new int[n+1];int top=-1;for(int i=0;i<=n;i++){int v=i==n?0:h[i];while(top>=0&&h[st[top]]>v){int height=h[st[top--]],left=top>=0?st[top]:-1;best=Math.max(best,height*(i-left-1));}st[++top]=i;}}return best;}
}

class Solution {
    public ListNode partition(ListNode head,int x){ListNode less=new ListNode(0),more=new ListNode(0),a=less,b=more;while(head!=null){ListNode next=head.next;head.next=null;if(head.val<x){a.next=head;a=head;}else{b.next=head;b=head;}head=next;}a.next=more.next;return less.next;}
}

from functools import lru_cache
from collections import Counter

class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        if len(s1)!=len(s2):return False
        @lru_cache(None)
        def dfs(a,b):
            if a==b:return True
            if Counter(a)!=Counter(b):return False
            for i in range(1,len(a)):
                if (dfs(a[:i],b[:i]) and dfs(a[i:],b[i:])) or (dfs(a[:i],b[-i:]) and dfs(a[i:],b[:-i])):return True
            return False
        return dfs(s1,s2)

import java.util.*;

class Solution {
    private Map<String,Boolean> memo;
    public boolean isScramble(String s1,String s2){if(s1.length()!=s2.length())return false;memo=new HashMap<>();return dfs(s1,s2);}
    private boolean dfs(String a,String b){if(a.equals(b))return true;String key=a+"#"+b;if(memo.containsKey(key))return memo.get(key);char[]x=a.toCharArray(),y=b.toCharArray();Arrays.sort(x);Arrays.sort(y);if(!Arrays.equals(x,y)){memo.put(key,false);return false;}for(int i=1;i<a.length();i++){if((dfs(a.substring(0,i),b.substring(0,i))&&dfs(a.substring(i),b.substring(i)))||(dfs(a.substring(0,i),b.substring(b.length()-i))&&dfs(a.substring(i),b.substring(0,b.length()-i)))){memo.put(key,true);return true;}}memo.put(key,false);return false;}
}

