    private void dfs(int[]a,int start,List<Integer>p,List<List<Integer>>out){out.add(new ArrayList<>(p));for(int i=start;i<a.length;i++){if(i>start&&a[i]==a[i-1])continue;p.add(a[i]);dfs(a,i+1,p,out);p.remove(p.size()-1);}}
}

class Solution:
    def numDecodings(self, s: str) -> int:
        if not s or s[0]=='0':return 0
        dp=[0]*(len(s)+1);dp[0]=dp[1]=1
        for i in range(2,len(s)+1):
            if s[i-1]!='0':dp[i]+=dp[i-1]
            pair=int(s[i-2:i])
            if 10<=pair<=26:dp[i]+=dp[i-2]
        return dp[-1]

class Solution {
    public int numDecodings(String s){if(s.isEmpty()||s.charAt(0)=='0')return 0;int[]dp=new int[s.length()+1];dp[0]=dp[1]=1;for(int i=2;i<=s.length();i++){if(s.charAt(i-1)!='0')dp[i]+=dp[i-1];int v=(s.charAt(i-2)-'0')*10+s.charAt(i-1)-'0';if(v>=10&&v<=26)dp[i]+=dp[i-2];}return dp[s.length()];}
}

