class Solution:
    def generateTrees(self, n: int) -> List[Optional[TreeNode]]:
        def build(lo,hi):
            if lo>hi:return [None]
            out=[]
            for value in range(lo,hi+1):
                for left in build(lo,value-1):
                    for right in build(value+1,hi):
                        root=TreeNode(value);root.left=left;root.right=right;out.append(root)
            return out
        return build(1,n)

import java.util.*;

class Solution {
    public List<TreeNode> generateTrees(int n){return build(1,n);}
    private List<TreeNode> build(int lo,int hi){List<TreeNode>out=new ArrayList<>();if(lo>hi){out.add(null);return out;}for(int v=lo;v<=hi;v++)for(TreeNode l:build(lo,v-1))for(TreeNode r:build(v+1,hi)){TreeNode root=new TreeNode(v);root.left=l;root.right=r;out.add(root);}return out;}
}

class Solution:
    def numTrees(self, n: int) -> int:
        dp=[0]*(n+1);dp[0]=1
        for nodes in range(1,n+1):
            for left in range(nodes):dp[nodes]+=dp[left]*dp[nodes-1-left]
        return dp[n]

class Solution {
    public int numTrees(int n){int[]dp=new int[n+1];dp[0]=1;for(int nodes=1;nodes<=n;nodes++)for(int left=0;left<nodes;left++)dp[nodes]+=dp[left]*dp[nodes-1-left];return dp[n];}
}

class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        m,n=len(s1),len(s2)
        if m+n!=len(s3):return False
        dp=[[False]*(n+1) for _ in range(m+1)];dp[0][0]=True
        for i in range(m+1):
            for j in range(n+1):
                if i>0 and s1[i-1]==s3[i+j-1]:dp[i][j]=dp[i][j] or dp[i-1][j]
                if j>0 and s2[j-1]==s3[i+j-1]:dp[i][j]=dp[i][j] or dp[i][j-1]
        return dp[m][n]

class Solution {
    public boolean isInterleave(String a,String b,String c){int m=a.length(),n=b.length();if(m+n!=c.length())return false;boolean[][]dp=new boolean[m+1][n+1];dp[0][0]=true;for(int i=0;i<=m;i++)for(int j=0;j<=n;j++){if(i>0&&a.charAt(i-1)==c.charAt(i+j-1))dp[i][j]|=dp[i-1][j];if(j>0&&b.charAt(j-1)==c.charAt(i+j-1))dp[i][j]|=dp[i][j-1];}return dp[m][n];}
}

